async function handleLemonWebhook(request, env) { const payload = await request.text(); let event; try { await verifyLemonSignature(payload, request.headers.get("x-signature"), env.LEMON_SQUEEZY_WEBHOOK_SECRET); } catch (error) { return json({ error: error instanceof Error ? error.message : "Invalid Lemon Squeezy signature." }, 400, request, env); } try { event = JSON.parse(payload); } catch { return json({ error: "Invalid Lemon Squeezy event payload." }, 400, request, env); } const payloadHash = hex(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(payload))); const eventId = `lemonsqueezy:${payloadHash}`; const ledgerEvent = { id: eventId, type: `lemonsqueezy.${event?.meta?.event_name || "unknown"}` }; try { if (!(await claimPaymentEvent(env, ledgerEvent))) return json({ received: true, duplicate: true }, 200, request, env); await processLemonEvent(env, event); await finishPaymentEvent(env, eventId, "processed"); return json({ received: true }, 200, request, env); } catch (error) { const message = error instanceof Error ? error.message : "Lemon Squeezy event processing failed."; await finishPaymentEvent(env, eventId, "failed", message).catch(() => undefined); return json({ error: message }, 500, request, env); } }
